  ('ee1873d0-efdf-4e31-907f-0a424ce37de8', '838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', null, 'topic'::public.curated_course_node_type, 'Physical Modeling, Measurement, Units, and Uncertainty', 'Students begin by learning how physics turns messy reality into measured quantities, models, estimates, and testable claims.', 0),
  ('c6d7e3c3-fb86-4eda-89ba-a508db3e6126', '838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'ee1873d0-efdf-4e31-907f-0a424ce37de8', 'subtopic'::public.curated_course_node_type, 'Models and approximations', 'The point is to learn that physics is built from idealized models chosen for a purpose.', 0),
