  ('e76dc211-c385-4171-8c20-b5b58b8bd64e', '838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', null, 'topic'::public.curated_course_node_type, 'Constraints, Circular Motion, Drag, and Reference Frames', 'Students extend Newton''s laws to coupled and constrained systems, curved motion, realistic resistive forces, and the careful choice of reference frame.', 4),
