  ('e5572ce3-e82a-418a-9215-e48afdb4bb57', '838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', '3126f931-d587-4f5a-8041-bc576f0032b5', 'concept'::public.curated_course_node_type, 'Numerical solutions', null, 2),
