  ('6a86d95e-8424-4b67-920f-66c1d500f285', '838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', '1ce7f75a-f6fc-4e1f-aaf8-ad0a45b2013c', 'concept'::public.curated_course_node_type, 'Centrifugal and Coriolis effects as qualitative previews', null, 1),
