insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'textbook'::public.curated_course_resource_kind, 'University Physics Volume 1', 'https://openstax.org/details/university-physics-volume-1', 'OpenStax. Free calculus-based spine for measurement, mechanics, rotation, gravitation, fluids, oscillations, waves, and sound.', 0),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'textbook'::public.curated_course_resource_kind, 'University Physics with Modern Physics', 'Pearson', 'Young and Freedman. Polished comprehensive text with strong derivations, applications, and problem sequences.', 1),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'textbook'::public.curated_course_resource_kind, 'Fundamentals of Physics', 'Wiley', 'Halliday, Resnick and Walker. Widely used alternative with extensive worked examples and graded problem practice.', 2),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'textbook'::public.curated_course_resource_kind, 'An Introduction to Mechanics', 'Cambridge University Press', 'Kleppner and Kolenkow. Challenging problems and deeper insight for high-achieving students and honors sections.', 3),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'textbook'::public.curated_course_resource_kind, 'Classical Mechanics', 'University Science Books', 'John R. Taylor. Selective later-course bridge for oscillations, central forces, rotating frames, and Lagrangian ideas.', 4),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'Classical Mechanics: MIT 8.01 Course Notes', 'https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/pages/online-textbook/', 'Peter Dourmashkin. A rigorous, course-aligned mechanics reference supporting the MIT sequence.', 5),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'MIT 8.01SC Classical Mechanics', 'https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/', 'Lectures, notes, worked examples, problem sets, and exams; especially strong on constraints, rotation, and conservation laws.', 6),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'MIT 8.01X: Experimental Focus', 'https://ocw.mit.edu/courses/8-01x-physics-i-classical-mechanics-with-an-experimental-focus-fall-2002/', 'Model for joining the mechanics syllabus to hands-on, take-home investigation.', 7),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'AAPT Goals and Laboratory Recommendations', 'https://www.aapt.org/resources/policy/goaloflabs.cfm', 'Guidance on experimental design, uncertainty, tools, modeling, collaboration, and the basis of physical knowledge.', 8),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'PhET Interactive Simulations', 'https://phet.colorado.edu/', 'Research-based interactive exploration for forces, energy, collisions, rotation, waves, and fluids.', 9),
  ('838eb2a0-2ccd-4b25-aa94-5cf9c04b6557', 'website'::public.curated_course_resource_kind, 'HyperPhysics', 'http://hyperphysics.phy-astr.gsu.edu/hbase/hframe.html', 'Fast review of relationships among concepts and equations; best used as a map, not a primary text.', 10),
